// Resolve probe URL + auth header per backend_kind.
//
// Strategy (OpenAI-compatible /v1/models is the lingua franca; works for
// direct_cloud Anthropic/OpenAI/Google/HuggingFace, llm_gateway, vLLM, and
// llmgateway.io. Ollama is the only outlier with /api/tags). When the
// registry has a custom health_url, prefer it (operator override).

const input = $input.first().json;
const { slug, backend_kind, endpoint_url, health_url, auth_env_var } = input;

// Trim trailing slashes for predictable concat
const baseUrl = String(endpoint_url || '').replace(/\/+$/, '');

let probeUrl = health_url;
if (!probeUrl) {
  if (backend_kind === 'local_ollama') {
    probeUrl = `${baseUrl}/api/tags`;
  } else {
    // direct_cloud + llm_gateway + local_vllm — all OpenAI-compatible
    probeUrl = `${baseUrl}/v1/models`;
  }
}

// Auth header — resolve env var at runtime. The env var name comes from the
// registry row (auth_env_var). If it's not set in the n8n container env,
// the probe goes through unauthenticated (some providers like Ollama don't
// need auth at all; for others a 401 still counts as 'reachable' and we
// treat it as healthy with a note).
const authToken = auth_env_var ? (process.env[auth_env_var] || '') : '';
const hasAuth = Boolean(authToken);

// Anthropic uses x-api-key + version header instead of Authorization Bearer
const isAnthropic = String(endpoint_url || '').includes('api.anthropic.com');

return [
  {
    json: {
      ...input,
      probe_url: probeUrl,
      probe_started_at: Date.now(),
      auth_header_name: isAnthropic ? 'x-api-key' : 'Authorization',
      auth_header_value: isAnthropic ? authToken : `Bearer ${authToken}`,
      has_auth: hasAuth,
    },
  },
];

// Classify probe result into status enum: healthy | degraded | down.
//
// Rules:
//   * HTTP 2xx + latency < 3s + parseable response → healthy
//   * HTTP 2xx + latency >= 3s → degraded (slow but works)
//   * HTTP 401/403 → healthy (provider is up; auth issue is operator's,
//     not provider's — resolver should keep considering it)
//   * HTTP 4xx (other) → degraded (endpoint exists but rejects probe)
//   * HTTP 5xx OR network error / timeout → down
//
// Failed probes (continueErrorOutput from HTTP node) come in as items with
// a top-level `error` field set. The fallback path covers that.

const orig = $('Resolve Probe Target').first().json;
const probeStartedAt = Number(orig.probe_started_at || Date.now());
const latencyMs = Date.now() - probeStartedAt;

let status = 'unknown';
let detail = '';

const input = $input.first().json;
const httpStatus = Number(input.statusCode || input.status || 0);

if (input.error) {
  status = 'down';
  detail = `network/timeout error: ${String(input.error).slice(0, 200)}`;
} else if (httpStatus >= 200 && httpStatus < 300) {
  status = latencyMs >= 3000 ? 'degraded' : 'healthy';
  detail = `HTTP ${httpStatus} in ${latencyMs}ms`;
} else if (httpStatus === 401 || httpStatus === 403) {
  // Service is reachable; auth is the operator's problem, not the
  // provider's reachability. We mark healthy so resolver keeps it in
  // the pool — the actual API call will fail loud-fast with the same
  // 401, and decisionProvenance will surface it.
  status = 'healthy';
  detail = `HTTP ${httpStatus} (auth issue — provider reachable; check ${orig.auth_env_var || 'auth'} env var)`;
} else if (httpStatus >= 400 && httpStatus < 500) {
  status = 'degraded';
  detail = `HTTP ${httpStatus} (4xx — endpoint exists but rejects probe)`;
} else if (httpStatus >= 500) {
  status = 'down';
  detail = `HTTP ${httpStatus} (5xx — provider error)`;
} else {
  status = 'down';
  detail = `Unexpected status ${httpStatus}`;
}

return [
  {
    json: {
      slug: orig.slug,
      backend_kind: orig.backend_kind,
      status,
      latency_ms: latencyMs,
      detail,
      http_status: httpStatus,
    },
  },
];
